input.new_string:
if balance_cents < 0 or days_late < 0:
    raise ValueError("balance_cents and days_late must be non-negative")
if balance_cents == 0 or days_late <= GRACE_DAYS:
    return 0
# Calculate started periods (ceiling division)
periods = (days_late + PERIOD_DAYS - 1) // PERIOD_DAYS
# Calculate fee with round-half-up
base_fee = (balance_cents * RATE_BP * periods + 5000) // 10000
cap = balance_cents // 5
# Cap wins if base fee exceeds it, otherwise apply minimum
if base_fee > cap:
    return cap
else:
    return max(base_fee, MINIMUM_FEE_CENTS)
